/** ISO 32000 §8.7 のパターン種別。 */
export const PdfPatternTypes = { Tiling: 1, Shading: 2 } as const;
export type PdfPatternType = ValueOf<typeof PdfPatternTypes>;

/** セル内で色を指定するか、呼び出し側から色を渡すか。 */
export const PdfPatternPaintTypes = { Colored: 1, Uncolored: 2 } as const;
export type PdfPatternPaintType = ValueOf<typeof PdfPatternPaintTypes>;

/** セルの間隔と形状を画素へ合わせる方式。 */
export const PdfPatternTilingTypes = {
  ConstantSpacing: 1,
  NoDistortion: 2,
  Faster: 3,
} as const;
export type PdfPatternTilingType = ValueOf<typeof PdfPatternTilingTypes>;

type PatternMatrix = readonly [number, number, number, number, number, number];

/** タイリングはセル、シェーディングは色変化の定義を保持する。 */
export type PdfPattern =
  | {
      readonly patternType: typeof PdfPatternTypes.Tiling;
      readonly stream: PdfStream;
      readonly paintType: PdfPatternPaintType;
      readonly tilingType: PdfPatternTilingType;
      readonly bbox: readonly [number, number, number, number];
      readonly xStep: number;
      readonly yStep: number;
      readonly resources: PdfDictionary;
      readonly matrix: PatternMatrix;
      readonly warnings: readonly PdfWarning[];
    }
  | {
      readonly patternType: typeof PdfPatternTypes.Shading;
      readonly dictionary: PdfDictionary;
      readonly shading: PdfShading;
      readonly extGState: Option<PdfDictionary>;
      readonly matrix: PatternMatrix;
      readonly warnings: readonly PdfWarning[];
    }
  | {
      readonly patternType: "Unknown";
      readonly object: PdfObject;
      readonly warnings: readonly PdfWarning[];
    };

/** 同期の色指定・描画命令から参照する、現在のスコープのパターンとシェーディング。 */
export type PaintResources = {
  readonly patterns: ReadonlyMap<string, Result<Option<PdfPattern>, PdfError>>;
  readonly shadings: ReadonlyMap<string, Result<Option<PdfShading>, PdfError>>;
};

export const PaintResources = {
  /** @returns 描画リソースのないスコープ */
  empty(): PaintResources {
    return { patterns: new Map(), shadings: new Map() };
  },

  /**
   * 同期実行前に /Pattern と /Shading の定義を解決する。
   * @param resources - 現在のページ・フォームのリソーススコープ
   * @param resolveRef - 同じ文書の参照解決関数
   * @returns カテゴリの参照エラーは Err、個別定義のエラーは使用時まで保持する
   */
  async fromResources(
    resources: PdfResources,
    resolveRef: ResolveRef,
  ): Promise<Result<PaintResources, PdfError>> {
    const patterns = await PaintResources.readCategory(
      resources,
      { name: "Pattern", read: PdfPattern.fromObject },
      resolveRef,
    );
    if (!patterns.ok) {
      return patterns;
    }

    const shadings = await PaintResources.readCategory(
      resources,
      { name: "Shading", read: PdfShading.fromObject },
      resolveRef,
    );
    if (!shadings.ok) {
      return shadings;
    }

    return ok({ patterns: patterns.value, shadings: shadings.value });
  },

    return err({
      code: "OPERATOR_OPERAND_COUNT_MISMATCH",
      operatorName: "sh",
      required: 1,
      actual,
      message: `Operator 'sh' requires 1 operand, got ${actual}`,
    });
  }

  const name = OperandExtractor.popName(context.operandStack, "sh");
  if (!name.ok) {
    return name;
  }

  const shading = resources.shadings.get(name.value) ?? ok(none);
  if (!shading.ok) {
    return shading;
  }

  return ok({
    ...context,
    warnings: shading.value.some
      ? shading.value.value.warnings
      : [
          {
            code: "SHADING_NOT_FOUND",
            message: `Shading resource not found: /${name.value}`,
          },
        ],
  });
};

