}

const parameters: ShadingParameters = {
  dictionary,
  colorSpace: colorSpace.value,
  background: background.value,
  bbox: bbox.value,
  function: fromNullable(dictionary.entries.get("Function")),
  warnings: [],
};
switch (shadingType.value) {
  case PdfShadingTypes.Function:
  case PdfShadingTypes.Axial:
  case PdfShadingTypes.Radial:
    return ok({ ...parameters, shadingType: shadingType.value });
  case PdfShadingTypes.FreeForm:
  case PdfShadingTypes.Lattice:
  case PdfShadingTypes.Coons:
  case PdfShadingTypes.Tensor:
    return ok(
      object.type === "stream"
        ? { ...parameters, shadingType: shadingType.value, stream: object }
        : PdfShading.unresolved(object, "SHADING_INVALID"),
    );
}

export const ColorOperation = {
  /**
   * 非着色パターンと基底色空間の組み合わせを検証する。
   * @param operation - 現在の色空間と色指定命令
   * @param pattern - 名前から取得したパターン
   * @returns 着色方式と基底の有無が一致しなければ不正状態のエラー
   */
  patternError(
    operation: ColorOperation,
    pattern: PdfPattern,
  ): Option<PdfOperatorIllegalStateError> {
    const space = operation.colorSpace;
    const hasPatternBase =
      typeof space !== "string" &&
      space.family === "Pattern" &&
      space.base.some;
    if (pattern.patternType === "Unknown") {
      return none;
    }

    const requiresBase = pattern.patternType === 1 && pattern.paintType === 2;
    return hasPatternBase !== requiresBase
      ? some({
          code: "OPERATOR_ILLEGAL_STATE",
          operatorName: operation.operatorName,
          message:
            "Pattern PaintType does not match the selected base color space",
        })
      : none;

   * 全ビルトインオペレータが登録されたデフォルトの `OperatorRegistry` を生成する。
   *
   * @param extGStates - 実行対象スコープの解決済み拡張状態
   * @param colorSpaces - 実行対象スコープの解決済み色空間
   * @param paints - 実行対象スコープの解決済みパターン・シェーディング
   * @returns 全ビルトインオペレータ登録済みの OperatorRegistry、または重複登録時の PdfError
   */
  createDefault(
    extGStates: ExtGStateResources = ExtGStateResources.empty(),
    colorSpaces: ColorSpaceResources = ColorSpaceResources.empty(),
    paints: PaintResources = PaintResources.empty(),
  ): Result<OperatorRegistry, PdfError> {
    const operators = [
      ...BUILTIN_OPERATORS,
      ...ColorSpaceOperators.create(colorSpaces, paints),
      ["sh", ShOperator.create(paints)] as const,
    ];
    return operators.reduce<Result<OperatorRegistry, PdfError>>(
      (acc, [name, handler]) =>
        flatMap(acc, (r) => OperatorRegistry.register(r, name, handler)),
      OperatorRegistry.register(
        OperatorRegistry.create(),
        "gs",
        GsOperator.create(extGStates),
      ),
    );
  },
} as const;

